    );
  });

  it("throws for non-positive upToGrams", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
    ).toThrow(RangeError);
  });

  it("throws for negative costCents", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: -1 }]),
    ).toThrow(RangeError);
  });

  it("throws for non-integer overflowCostCents", () => {
    expect(
      () =>
        new WeightBasedShippingCalculator(
          [{ upToGrams: 1000, costCents: 100 }],
          5.5,
        ),
    ).toThrow(RangeError);
  });

  it("throws for negative overflowCostCents", () => {
    expect(
      () =>
        new WeightBasedShippingCalculator(
          [{ upToGrams: 1000, costCents: 100 }],
          -1,
        ),
    ).toThrow(RangeError);
  });

  it("returns 0 for empty cart", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 1000, costCents: 500 },
    ]);
    expect(calc.computeShippingCents([], 10000)).toBe(0);
  });

  it("returns 0 when total weight is 0 (no weightGrams set)", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 1000, costCents: 500 },
    ]);
    expect(
      calc.computeShippingCents([makeLine("a", 1000, 1)], 1000),
    ).toBe(0);
  });

  it("selects lowest bracket that fits the weight", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
      { upToGrams: 5000, costCents: 1200 },
    ]);
    // 400g fits in first bracket (500)
    expect(
      calc.computeShippingCents([makeLine("a", 1000, 1, 400)], 1000),
    ).toBe(300);
  });

  it("uses exact boundary of bracket", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
    ]);
    // Exactly 500g fits in first bracket
    expect(
      calc.computeShippingCents([makeLine("a", 1000, 1, 500)], 1000),
    ).toBe(300);
    // 501g fits in second bracket
    expect(
      calc.computeShippingCents([makeLine("a", 1000, 1, 501)], 1000),
    ).toBe(600);
  });

  it("uses overflow cost when weight exceeds all brackets", () => {
    const calc = new WeightBasedShippingCalculator(
      [
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 600 },
      ],
      2000,
    );
    expect(
      calc.computeShippingCents([makeLine("a", 1000, 1, 1500)], 1000),
    ).toBe(2000);
  });

  it("defaults to heaviest bracket cost when no overflow specified", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
    ]);
    expect(
      calc.computeShippingCents([makeLine("a", 1000, 1, 5000)], 1000),
    ).toBe(600);
  });

  it("sorts brackets internally regardless of input order", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 5000, costCents: 1200 },
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
    ]);
    // 400g should still hit the 500g bracket
    expect(
      calc.computeShippingCents([makeLine("a", 1000, 1, 400)], 1000),
    ).toBe(300);
  });

  it("accounts for quantity in weight calculation", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
    ]);
    // 3 items at 200g each = 600g, second bracket
    expect(
      calc.computeShippingCents([makeLine("a", 1000, 3, 200)], 3000),
    ).toBe(600);
  });
});

