import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import { InventoryError } from "../src/inventory.ts";
import type { Product } from "../src/product.ts";

const productA: Product = { id: "a", name: "Widget", unitPriceCents: 1000 };
const productB: Product = { id: "b", name: "Gadget", unitPriceCents: 2000, weightGrams: 500 };

describe("Cart - line management", () => {
  it("starts empty", () => {
    const cart = new Cart();
    expect(cart.itemCount).toBe(0);
    expect(cart.totals().subtotalCents).toBe(0);
  });

  it("adds a product", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    expect(cart.itemCount).toBe(2);
  });

  it("merges quantities for same product", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    cart.add(productA, 3);
    expect(cart.itemCount).toBe(5);
  });

  it("throws for non-positive quantity on add", () => {
    const cart = new Cart();
    expect(() => cart.add(productA, 0)).toThrow(RangeError);
    expect(() => cart.add(productA, -1)).toThrow(RangeError);
    expect(() => cart.add(productA, 1.5)).toThrow(RangeError);
  });

  it("throws for negative unit price on add", () => {
    const cart = new Cart();
    const bad: Product = { id: "x", name: "Bad", unitPriceCents: -1 };
    expect(() => cart.add(bad, 1)).toThrow(RangeError);
  });

  it("removes a product and returns true", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("returns false for removing unknown product", () => {
    const cart = new Cart();
    expect(cart.remove("unknown")).toBe(false);
  });

  it("updateQuantity changes quantity", () => {
    const cart = new Cart();
    cart.add(productA, 5);
    cart.updateQuantity("a", 3);
    expect(cart.itemCount).toBe(3);
  });

  it("updateQuantity to 0 removes the product", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
    expect(cart.remove("a")).toBe(false);
  });

  it("updateQuantity throws for unknown product", () => {
    const cart = new Cart();
    expect(() => cart.updateQuantity("unknown", 5)).toThrow("not in the cart");
  });

  it("updateQuantity throws for negative quantity", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("clear empties the cart", () => {
    const cart = new Cart();
    cart.add(productA, 3);
    cart.add(productB, 2);
    cart.clear();
    expect(cart.itemCount).toBe(0);
    expect(cart.totals().subtotalCents).toBe(0);
  });

  it("snapshot returns deep copy", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    const snap = cart.snapshot();
    snap[0].quantity = 999;
    expect(cart.itemCount).toBe(1);
  });
});

describe("Cart - pricing pipeline", () => {
  it("computes subtotal as sum of price * quantity", () => {
    const cart = new Cart();
    cart.add(productA, 2); // 2000
    cart.add(productB, 1); // 2000
    expect(cart.totals().subtotalCents).toBe(4000);
  });

  it("applies discount policy to subtotal", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({ discountPolicy: discount });
    cart.add(productA, 1); // subtotal 1000
    const totals = cart.totals();
    expect(discount.computeDiscountCents).toHaveBeenCalledWith(1000);
    expect(totals.discountCents).toBe(500);
  });

  it("clamps discount to [0, subtotal]", () => {
    const overDiscount: DiscountPolicy = {
      computeDiscountCents: () => 99999,
    };
    const cart = new Cart({ discountPolicy: overDiscount });
    cart.add(productA, 1);
    expect(cart.totals().discountCents).toBe(1000); // clamped to subtotal

    const negDiscount: DiscountPolicy = {
      computeDiscountCents: () => -100,
    };
    const cart2 = new Cart({ discountPolicy: negDiscount });
    cart2.add(productA, 1);
    expect(cart2.totals().discountCents).toBe(0); // clamped to 0
  });

  it("applies tax on discounted subtotal", () => {
    const discount: DiscountPolicy = { computeDiscountCents: () => 200 };
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(80),
    };
    const cart = new Cart({ discountPolicy: discount, taxCalculator: tax, region: "US-CA" });
    cart.add(productA, 1); // subtotal 1000, discount 200, taxable 800
    cart.totals();
    expect(tax.computeTaxCents).toHaveBeenCalledWith(800, "US-CA");
  });

  it("applies shipping on lines and discounted subtotal", () => {
    const discount: DiscountPolicy = { computeDiscountCents: () => 100 };
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(599),
    };
    const cart = new Cart({ discountPolicy: discount, shippingCalculator: shipping });
    cart.add(productA, 1); // subtotal 1000, discounted 900
    const totals = cart.totals();
    expect(shipping.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      900,
    );
    expect(totals.shippingCents).toBe(599);
  });

  it("total = discountedSubtotal + tax + shipping", () => {
    const discount: DiscountPolicy = { computeDiscountCents: () => 200 };
    const tax: TaxCalculator = { computeTaxCents: () => 80 };
    const shipping: ShippingCalculator = { computeShippingCents: () => 500 };
    const cart = new Cart({
      discountPolicy: discount,
      taxCalculator: tax,
      shippingCalculator: shipping,
    });
    cart.add(productA, 1); // subtotal 1000
    const totals = cart.totals();
    // discounted = 1000 - 200 = 800
    // total = 800 + 80 + 500 = 1380
    expect(totals.totalCents).toBe(1380);
  });

  it("defaults to no discount, no tax, free shipping, region US", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    const totals = cart.totals();
    expect(totals.discountCents).toBe(0);
    expect(totals.taxCents).toBe(0);
    expect(totals.shippingCents).toBe(0);
    expect(totals.totalCents).toBe(1000);
  });

  it("clamps negative tax to 0", () => {
    const tax: TaxCalculator = { computeTaxCents: () => -50 };
    const cart = new Cart({ taxCalculator: tax });
    cart.add(productA, 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const shipping: ShippingCalculator = { computeShippingCents: () => -100 };
    const cart = new Cart({ shippingCalculator: shipping });
    cart.add(productA, 1);
    expect(cart.totals().shippingCents).toBe(0);
  });
});

describe("Cart - checkout()", () => {
  it("returns totals and lines for basic checkout", async () => {
    const cart = new Cart();
    cart.add(productA, 1);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(1000);
    expect(result.lines).toHaveLength(1);
  });

  it("refreshes prices via priceFetcher", async () => {
    const cart = new Cart();
    cart.add(productA, 2);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1500),
    };
    const result = await cart.checkout({ priceFetcher });
    expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("a");
    expect(result.totals.subtotalCents).toBe(3000); // 1500 * 2
  });

  it("checks inventory and passes for available items", async () => {
    const cart = new Cart();
    cart.add(productA, 2);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
    };
    const result = await cart.checkout({ inventoryChecker });
    expect(inventoryChecker.check).toHaveBeenCalledWith("a", 2);
    expect(result.totals.subtotalCents).toBe(2000);
  });

  it("throws InventoryError when item unavailable", async () => {
    const cart = new Cart();
    cart.add(productA, 2);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        availableQuantity: 0,
        reason: "out of stock",
      }),
    };
    await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(InventoryError);
    try {
      await cart.checkout({ inventoryChecker });
    } catch (e) {
      const err = e as InventoryError;
      expect(err.productId).toBe("a");
      expect(err.requested).toBe(2);
      expect(err.available).toBe(0);
    }
  });

  it("throws InventoryError for partial-stock denial", async () => {
    const cart = new Cart();
    cart.add(productA, 5);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      }),
    };
    await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(InventoryError);
    try {
      await cart.checkout({ inventoryChecker });
    } catch (e) {
      const err = e as InventoryError;
      expect(err.productId).toBe("a");
      expect(err.requested).toBe(5);
      expect(err.available).toBe(3);
    }
  });

  it("uses asyncTaxProvider for tax calculation", async () => {
    const discount: DiscountPolicy = { computeDiscountCents: () => 200 };
    const cart = new Cart({ discountPolicy: discount, region: "US-NY" });
    cart.add(productA, 1); // subtotal 1000, discount 200, taxable 800
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const result = await cart.checkout({ asyncTaxProvider });
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-NY");
    // tax = Math.floor(800 * 0.1) = 80
    expect(result.totals.taxCents).toBe(80);
  });

  it("combines priceFetcher, inventoryChecker, and asyncTaxProvider", async () => {
    const shipping: ShippingCalculator = { computeShippingCents: () => 500 };
    const cart = new Cart({ shippingCalculator: shipping, region: "US" });
    cart.add(productA, 1);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(2000),
    };
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.05),
    };

    const result = await cart.checkout({ priceFetcher, inventoryChecker, asyncTaxProvider });
    // subtotal: 2000, discount: 0, taxable: 2000
    // tax: Math.floor(2000 * 0.05) = 100
    // shipping: 500
    // total: 2000 + 100 + 500 = 2600
    expect(result.totals.subtotalCents).toBe(2000);
    expect(result.totals.taxCents).toBe(100);
    expect(result.totals.shippingCents).toBe(500);
    expect(result.totals.totalCents).toBe(2600);
  });

  it("propagates asyncTaxProvider rejection", async () => {
    const cart = new Cart();
    cart.add(productA, 1);
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
    };
    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow("tax service down");
  });

  it("propagates priceFetcher rejection", async () => {
    const cart = new Cart();
    cart.add(productA, 1);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("price service error")),
    };
    await expect(cart.checkout({ priceFetcher })).rejects.toThrow("price service error");
  });

  it("works with empty cart", async () => {
    const cart = new Cart();
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(0);
    expect(result.totals.totalCents).toBe(0);
    expect(result.lines).toHaveLength(0);
  });
});

