import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it("returns 0 for positive subtotal", () => {
    expect(policy.computeDiscountCents(10000)).toBe(0);
  });

  it("returns 0 for zero subtotal", () => {
    expect(policy.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    expect(policy.computeDiscountCents(-500)).toBe(0);
  });
});

describe("PercentageDiscountPolicy", () => {
  it("throws RangeError for negative percent", () => {
    expect(() => new PercentageDiscountPolicy(-1)).toThrow(RangeError);
  });

  it("throws RangeError for percent > 100", () => {
    expect(() => new PercentageDiscountPolicy(101)).toThrow(RangeError);
  });

  it("throws RangeError for NaN", () => {
    expect(() => new PercentageDiscountPolicy(NaN)).toThrow(RangeError);
  });

  it("throws RangeError for Infinity", () => {
    expect(() => new PercentageDiscountPolicy(Infinity)).toThrow(RangeError);
  });

  it("accepts 0 percent", () => {
    const policy = new PercentageDiscountPolicy(0);
    expect(policy.computeDiscountCents(10000)).toBe(0);
  });

  it("accepts 100 percent", () => {
    const policy = new PercentageDiscountPolicy(100);
    expect(policy.computeDiscountCents(10000)).toBe(10000);
  });

  it("computes 10% discount rounded down", () => {
    const policy = new PercentageDiscountPolicy(10);
    expect(policy.computeDiscountCents(1001)).toBe(100); // Math.floor(1001 * 10 / 100) = 100
  });

  it("rounds down fractional cents", () => {
    const policy = new PercentageDiscountPolicy(33);
    // Math.floor(100 * 33 / 100) = 33
    expect(policy.computeDiscountCents(100)).toBe(33);
    // Math.floor(1 * 33 / 100) = 0
    expect(policy.computeDiscountCents(1)).toBe(0);
  });

  it("returns 0 for zero subtotal", () => {
    const policy = new PercentageDiscountPolicy(50);
    expect(policy.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    const policy = new PercentageDiscountPolicy(50);
    expect(policy.computeDiscountCents(-1000)).toBe(0);
  });

  it("handles very large subtotal", () => {
    const policy = new PercentageDiscountPolicy(15);
    expect(policy.computeDiscountCents(10_000_000)).toBe(1_500_000);
  });
});

describe("FixedAmountDiscountPolicy", () => {
  it("throws RangeError for negative amount", () => {
    expect(() => new FixedAmountDiscountPolicy(-1)).toThrow(RangeError);
  });

  it("throws RangeError for non-integer amount", () => {
    expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
  });

  it("accepts 0 amount", () => {
    const policy = new FixedAmountDiscountPolicy(0);
    expect(policy.computeDiscountCents(5000)).toBe(0);
  });

  it("returns the fixed amount when subtotal is larger", () => {
    const policy = new FixedAmountDiscountPolicy(500);
    expect(policy.computeDiscountCents(10000)).toBe(500);
  });

  it("caps at subtotal when amount exceeds subtotal", () => {
    const policy = new FixedAmountDiscountPolicy(5000);
    expect(policy.computeDiscountCents(3000)).toBe(3000);
  });

  it("returns 0 for zero subtotal", () => {
    const policy = new FixedAmountDiscountPolicy(500);
    expect(policy.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    const policy = new FixedAmountDiscountPolicy(500);
    expect(policy.computeDiscountCents(-100)).toBe(0);
  });
});

describe("CompositeDiscountPolicy", () => {
  it("throws when given empty array of policies", () => {
    expect(() => new CompositeDiscountPolicy([])).toThrow(
      "CompositeDiscountPolicy requires at least one policy",
    );
  });

  describe("sum mode", () => {
    it("sums discounts from all child policies", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10),
          new FixedAmountDiscountPolicy(200),
        ],
        "sum",
      );
      // 10% of 10000 = 1000, fixed 200 => sum = 1200
      expect(composite.computeDiscountCents(10000)).toBe(1200);
    });

    it("each policy receives original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(50),
          new PercentageDiscountPolicy(50),
        ],
        "sum",
      );
      // 50% + 50% = 100% of subtotal (can exceed subtotal; Cart clamps)
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(-500)).toBe(0);
    });

    it("clamps negative child results to 0 before summing", () => {
      // NoDiscountPolicy returns 0 always, so just verify no negatives
      const composite = new CompositeDiscountPolicy(
        [new NoDiscountPolicy(), new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      expect(composite.computeDiscountCents(5000)).toBe(100);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(50),
          new PercentageDiscountPolicy(50),
        ],
        "chain",
      );
      // First: 50% of 1000 = 500, remaining = 500
      // Second: 50% of 500 = 250, remaining = 250
      // Total discount: 750
      expect(composite.computeDiscountCents(1000)).toBe(750);
    });

    it("order of policies matters in chain mode", () => {
      const composite1 = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(200),
          new PercentageDiscountPolicy(50),
        ],
        "chain",
      );
      // Fixed 200 from 1000 => remaining 800; 50% of 800 = 400 => total 600
      expect(composite1.computeDiscountCents(1000)).toBe(600);

      const composite2 = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(50),
          new FixedAmountDiscountPolicy(200),
        ],
        "chain",
      );
      // 50% of 1000 = 500 => remaining 500; fixed 200 => total 700
      expect(composite2.computeDiscountCents(1000)).toBe(700);
    });

    it("stops when remaining reaches 0", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(1000),
          new PercentageDiscountPolicy(50),
        ],
        "chain",
      );
      // Fixed takes all 1000, remaining = 0; 50% of 0 = 0 => total 1000
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "chain",
      );
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });
  });

  it("defaults to sum mode when not specified", () => {
    const composite = new CompositeDiscountPolicy([
      new PercentageDiscountPolicy(10),
      new FixedAmountDiscountPolicy(100),
    ]);
    // sum mode: 10% of 1000 = 100, plus 100 => 200
    expect(composite.computeDiscountCents(1000)).toBe(200);
  });
});

