toolArgs.file_text:
import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
} from "../src/shipping.ts";
import type { CartLine } from "../src/product.ts";

const makeLine = (
  id: string,
  price: number,
  qty: number,
  weight?: number,
): CartLine => ({
  product: { id, name: id, unitPriceCents: price, weightGrams: weight },
  quantity: qty,
});

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("returns 0 for non-empty cart", () => {
    expect(calc.computeShippingCents([makeLine("a", 1000, 1)], 1000)).toBe(0);
  });

  it("returns 0 for empty cart", () => {
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  it("throws RangeError for negative flatCents", () => {
    expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
  });

  it("throws RangeError for non-integer flatCents", () => {
    expect(() => new FlatShippingCalculator(5.5)).toThrow(RangeError);
  });

  it("throws RangeError for negative freeOverCents", () => {
    expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
  });

  it("throws RangeError for non-integer freeOverCents", () => {
    expect(() => new FlatShippingCalculator(500, 99.9)).toThrow(RangeError);
  });

  it("returns 0 for empty cart", () => {
    const calc = new FlatShippingCalculator(500);
    expect(calc.computeShippingCents([], 10000)).toBe(0);
  });

  it("returns flat fee for non-empty cart", () => {
    const calc = new FlatShippingCalculator(599);
    expect(calc.computeShippingCents([makeLine("a", 1000, 1)], 1000)).toBe(599);
  });

  it("returns 0 when subtotal >= freeOverCents threshold", () => {
    const calc = new FlatShippingCalculator(500, 5000);
    expect(calc.computeShippingCents([makeLine("a", 5000, 1)], 5000)).toBe(0);
  });

  it("returns flat fee when subtotal is below freeOverCents threshold", () => {
    const calc = new FlatShippingCalculator(500, 5000);
    expect(calc.computeShippingCents([makeLine("a", 4999, 1)], 4999)).toBe(500);
  });

  it("returns 0 when subtotal equals freeOverCents exactly", () => {
    const calc = new FlatShippingCalculator(500, 3000);
    expect(calc.computeShippingCents([makeLine("a", 3000, 1)], 3000)).toBe(0);
  });

  it("accepts flatCents of 0", () => {
    const calc = new FlatShippingCalculator(0);
    expect(calc.computeShippingCents([makeLine("a", 1000, 1)], 1000)).toBe(0);
  });
});

describe("WeightBasedShippingCalculator", () => {
  it("throws when given empty brackets array", () => {
    expect(() => new WeightBasedShippingCalculator([])).toThrow(
      "at least one weight bracket is required",
    );
  });

  it("throws for non-positive upToGrams", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
    ).toThrow(RangeError);
  });

  it("throws for negative costCents", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: -1 }]),
    ).toThrow(RangeError);
  });

  it("throws for non-integer overflowCostCents", () => {
    expect(
      () =>
        new WeightBasedShippingCalculator(
          [{ upToGrams: 1000, costCents: 100 }],
          5.5,
        ),
    ).toThrow(RangeError);
  });

  it("throws for negative overflowCostCents", () => {
    expect(
      () =>
        new WeightBasedShippingCalculator(
          [{ upToGrams: 1000, costCents: 100 }],
          -1,
        ),
    ).toThrow(RangeError);
  });

  it("returns 0 for empty cart", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 1000, costCents: 500 },
    ]);
    expect(calc.computeShippingCents([], 10000)).toBe(0);
  });

  it("returns 0 when total weight is 0 (no weightGrams set)", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 1000, costCents: 500 },
    ]);
    expect(
      calc.computeShippingCents([makeLine("a", 1000, 1)], 1000),
    ).toBe(0);
  });

  it("selects lowest bracket that fits the weight", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
      { upToGrams: 5000, costCents: 1200 },
    ]);
    // 400g fits in first bracket (500)
    expect(
      calc.computeShippingCents([makeLine("a", 1000, 1, 400)], 1000),
    ).toBe(300);
  });

  it("uses exact boundary of bracket", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
    ]);
    // Exactly 500g fits in first bracket
    expect(
      calc.computeShippingCents([makeLine("a", 1000, 1, 500)], 1000),
    ).toBe(300);
    // 501g fits in second bracket
    expect(
      calc.computeShippingCents([makeLine("a", 1000, 1, 501)], 1000),
    ).toBe(600);
  });

  it("uses overflow cost when weight exceeds all brackets", () => {
    const calc = new WeightBasedShippingCalculator(
      [
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 600 },
      ],
      2000,
    );
    expect(
      calc.computeShippingCents([makeLine("a", 1000, 1, 1500)], 1000),
    ).toBe(2000);
  });

  it("defaults to heaviest bracket cost when no overflow specified", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
    ]);
    expect(
      calc.computeShippingCents([makeLine("a", 1000, 1, 5000)], 1000),
    ).toBe(600);
  });

  it("sorts brackets internally regardless of input order", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 5000, costCents: 1200 },
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
    ]);
    // 400g should still hit the 500g bracket
    expect(
      calc.computeShippingCents([makeLine("a", 1000, 1, 400)], 1000),
    ).toBe(300);
  });

  it("accounts for quantity in weight calculation", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
    ]);
    // 3 items at 200g each = 600g, second bracket
    expect(
      calc.computeShippingCents([makeLine("a", 1000, 3, 200)], 3000),
    ).toBe(600);
  });
});

